import { openDB, type IDBPDatabase } from 'idb';
import type { SessionMapping, VaultInterface } from '@airlock/scrub-engine';

/**
 * Encrypted local vault (BRIEF §P0-4). Session mappings live in IndexedDB, encrypted with
 * AES-GCM under a NON-EXTRACTABLE CryptoKey generated by WebCrypto and stored (as a key
 * handle, never as bytes) in a separate IndexedDB store. Nothing here ever touches the
 * network, Firestore, logs or analytics. Entries expire after their TTL.
 */

interface SessionRecord {
  id: string;
  iv: Uint8Array<ArrayBuffer>;
  data: ArrayBuffer;
  expiresAt: number;
}

const DB_NAME = 'airlock-vault';

let dbPromise: Promise<IDBPDatabase> | null = null;
function vaultDb(): Promise<IDBPDatabase> {
  dbPromise ??= openDB(DB_NAME, 1, {
    upgrade(d) {
      d.createObjectStore('keys');
      d.createObjectStore('sessions', { keyPath: 'id' });
    },
  });
  return dbPromise;
}

/** The vault key: created once, non-extractable, usable only for encrypt/decrypt. */
async function vaultKey(): Promise<CryptoKey> {
  const d = await vaultDb();
  const existing = (await d.get('keys', 'vault')) as CryptoKey | undefined;
  if (existing) return existing;
  const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
  await d.put('keys', key, 'vault');
  return key;
}

/** Maps and Sets are not JSON: turn a mapping into plain arrays and back. */
export function serializeMapping(m: SessionMapping): string {
  return JSON.stringify({
    forward: [...m.forward],
    reverse: [...m.reverse],
    aliases: [...m.aliases],
    aliasForward: [...m.aliasForward],
    originals: [...m.originals],
    seed: m.seed,
  });
}

export function deserializeMapping(json: string): SessionMapping {
  const o = JSON.parse(json);
  return {
    forward: new Map(o.forward),
    reverse: new Map(o.reverse),
    aliases: new Map(o.aliases),
    aliasForward: new Map(o.aliasForward ?? []),
    originals: new Set(o.originals),
    seed: o.seed >>> 0,
  };
}

/** A random 32-bit session seed for the stand-in PRNG (BRIEF §8.2). */
export function randomSeed(): number {
  return crypto.getRandomValues(new Uint32Array(1))[0];
}

/**
 * Creates a vault backed by IndexedDB. Encrypts with AES-GCM, non-extractable key.
 * Key is stored in a separate IDB object store.
 * BRIEF §P0-4.
 */
export function createVault(): VaultInterface {
  return {
    async store(sessionId, mapping, ttlHours) {
      const key = await vaultKey();
      const iv = crypto.getRandomValues(new Uint8Array(new ArrayBuffer(12)));
      const data = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, new TextEncoder().encode(serializeMapping(mapping)));
      const record: SessionRecord = { id: sessionId, iv, data, expiresAt: Date.now() + ttlHours * 3600_000 };
      await (await vaultDb()).put('sessions', record);
    },
    async load(sessionId) {
      const d = await vaultDb();
      const record = (await d.get('sessions', sessionId)) as SessionRecord | undefined;
      if (!record) return null;
      if (record.expiresAt <= Date.now()) {
        await d.delete('sessions', sessionId);
        return null;
      }
      try {
        const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: record.iv }, await vaultKey(), record.data);
        return deserializeMapping(new TextDecoder().decode(plain));
      } catch {
        await d.delete('sessions', sessionId);
        return null;
      }
    },
    async forget(sessionId) {
      await (await vaultDb()).delete('sessions', sessionId);
    },
    async forgetAll() {
      await (await vaultDb()).clear('sessions');
    },
    async isExpired(sessionId) {
      const record = (await (await vaultDb()).get('sessions', sessionId)) as SessionRecord | undefined;
      return !record || record.expiresAt <= Date.now();
    },
  };
}

/** Deletes expired sessions (run at startup: the automatic TTL wipe). */
export async function purgeExpiredSessions(): Promise<number> {
  const d = await vaultDb();
  const all = (await d.getAll('sessions')) as SessionRecord[];
  const expired = all.filter((r) => r.expiresAt <= Date.now());
  await Promise.all(expired.map((r) => d.delete('sessions', r.id)));
  return expired.length;
}
